sys_script_include.script:
var CanopiServerProcessor = Class.create()
CanopiServerProcessor.prototype = {
    initialize: function() {},

    processRecord: function(stagingSysId) {
        var stg = new GlideRecord('x_2226556_server_0_canopi_stg');
        if (!stg.get(stagingSysId)) {
            gs.error('CanopiServerProcessor: Staging record not found: ' + stagingSysId);
            return { status: 'error', message: 'Staging record not found' };
        }

        var payloadStr = stg.getValue('payload');
        if (!payloadStr) {
            this._updateStaging(stg, 'error', '', '', 'Payload is empty', '400');
            return { status: 'error', message: 'Payload is empty' };
        }

        var payload;
        try {
            payload = JSON.parse(payloadStr);
        } catch (e) {
            this._updateStaging(stg, 'error', '', '', 'Invalid JSON payload: ' + e, '400');
            return { status: 'error', message: 'Invalid JSON payload' };
        }

        // ─── STEP 1: ETL Field Mapping ──────────────────────────────────
        var ciData = this._applyETLMappings(payload);
        gs.info('CanopiServerProcessor: ETL mappings applied for staging ' + stagingSysId);

        // ─── STEP 2: Try IRE first, fallback to direct insert ───────────
        var result = this._invokeIRE(ciData, stagingSysId);

        if (!result || !result.sysId) {
            gs.warn('CanopiServerProcessor: IRE did not return a valid CI. Falling back to direct GlideRecord insert.');
            result = this._directInsert(ciData, stagingSysId);
        }

        if (!result || !result.sysId) {
            this._updateStaging(stg, 'error', '', '', 'Failed to create CI via IRE and direct insert', '500');
            return { status: 'error', message: 'Failed to create server CI record' };
        }

        // ─── STEP 3: Update staging record with CMDB result ─────────────
        var responseMsg = 'CI ' + result.operation + ' successfully. Class: ' + result.className + ', Record ID: ' + result.sysId;
        this._updateStaging(stg, 'processed', result.className, result.sysId, responseMsg, '200');
        gs.info('CanopiServerProcessor: Staging ' + stagingSysId + ' → ' + result.operation + ' CI ' + result.sysId);

        return {
            status: 'success',
            operation: result.operation,
            ci_sys_id: result.sysId,
            ci_class: result.className,
            message: responseMsg
        };
    },

    _applyETLMappings: function(payload) {
        var device = payload.device || {};

        return {
            name: payload.hostName || '',
            host_name: payload.hostName || '',
            dns_domain: payload.dnsDomain || '',
            serial_number: payload.serialNumber || '',
            short_description: device.description || '',
            environment: device.environment || '',
            used_for: device.used_for || '',
            correlation_id: payload.orderId || '',
            discovery_source: 'CANOPI',
            fqdn: (payload.hostName || '') + '.' + (payload.dnsDomain || '')
        };
    },

    /**
     * Invokes CMDB IRE. The input format must NOT include 'lookup' —
     * IRE uses the CI Identifier rules configured on the platform.
     */
    _invokeIRE: function(ciData, stagingSysId) {
        try {
            var input = {
                items: [{
                    className: 'cmdb_ci_server',
                    values: ciData
                }]
            };

            var jsonInput = JSON.stringify(input);
            gs.info('CanopiServerProcessor: IRE input for staging ' + stagingSysId + ': ' + jsonInput);

            var output = sn_cmdb.IdentificationEngine.createOrUpdateCI('CANOPI', jsonInput);
            gs.info('CanopiServerProcessor: IRE raw output for staging ' + stagingSysId + ': ' + output);

            if (output) {
                var result;
                if (typeof output === 'string') {
                    result = JSON.parse(output);
                } else {
                    result = output;
                }

                if (result.items && result.items.length > 0) {
                    var item = result.items[0];
                    // IRE response may use sysId or sys_id depending on version
                    var ciSysId = item.sysId || item.sys_id || '';
                    var ciClass = item.className || item.class_name || 'cmdb_ci_server';
                    var op = item.operation || 'unknown';

                    gs.info('CanopiServerProcessor: IRE result - sysId: ' + ciSysId + ', class: ' + ciClass + ', operation: ' + op);

                    if (ciSysId) {
                        return { sysId: ciSysId, className: ciClass, operation: op };
                    }
                }

                // Log full item for debugging
                if (result.items && result.items.length > 0) {
                    gs.warn('CanopiServerProcessor: IRE item had no sysId. Full item: ' + JSON.stringify(result.items[0]));
                }
            }

            gs.error('CanopiServerProcessor: IRE returned no usable result for staging ' + stagingSysId);
            return null;

        } catch (e) {
            gs.error('CanopiServerProcessor: IRE error for staging ' + stagingSysId + ': ' + e);
            return null;
        }
    },

    /**
     * Direct GlideRecord insert as fallback when IRE is unavailable
     * or fails to return a valid CI.
     */
    _directInsert: function(ciData, stagingSysId) {
        try {
            // First check if a CI already exists with same host_name + dns_domain
            var existing = new GlideRecord('cmdb_ci_server');
            existing.addQuery('host_name', ciData.host_name);
            existing.addQuery('dns_domain', ciData.dns_domain);
            existing.query();

            if (existing.next()) {
                // Update existing CI
                for (var updateField in ciData) {
                    if (ciData.hasOwnProperty(updateField) && ciData[updateField]) {
                        existing.setValue(updateField, ciData[updateField]);
                    }
                }
                existing.update();
                gs.info('CanopiServerProcessor: Direct update CI ' + existing.getUniqueValue() + ' for staging ' + stagingSysId);
                return {
                    sysId: existing.getUniqueValue(),
                    className: existing.getValue('sys_class_name') || 'cmdb_ci_server',
                    operation: 'update'
                };
            }

            // Insert new CI
            var gr = new GlideRecord('cmdb_ci_server');
            gr.initialize();
            for (var field in ciData) {
                if (ciData.hasOwnProperty(field) && ciData[field]) {
                    gr.setValue(field, ciData[field]);
                }
            }
            var newSysId = gr.insert();

            if (newSysId) {
                gs.info('CanopiServerProcessor: Direct insert CI ' + newSysId + ' for staging ' + stagingSysId);
                return {
                    sysId: String(newSysId),
                    className: 'cmdb_ci_server',
                    operation: 'insert'
                };
            }

            gs.error('CanopiServerProcessor: Direct insert failed for staging ' + stagingSysId);
            return null;

        } catch (e) {
            gs.error('CanopiServerProcessor: Direct insert error for staging ' + stagingSysId + ': ' + e);
            return null;
        }
    },

    _updateStaging: function(stg, state, targetTable, targetRecord, message, httpCode) {
        stg.setValue('sys_import_state', state);
        if (targetTable) stg.setValue('sys_target_table', targetTable);
        if (targetRecord) stg.setValue('sys_target_sys_id', targetRecord);
        stg.setValue('response_message', message);
        stg.setValue('http_response_code', httpCode);
        stg.update();
    },

    type: 'CanopiServerProcessor'
}
